package com.example.starter.pass.service;

import com.example.starter.pass.api.AllocateRequest;
import com.example.starter.pass.api.CancelRequest;
import com.example.starter.pass.api.CompleteRequest;
import com.example.starter.pass.api.PredictionUpsertRequest;
import com.example.starter.pass.api.PredictionView;
import com.example.starter.pass.api.ReassignRequest;
import com.example.starter.pass.api.SlotView;
import com.example.starter.pass.clock.TimeSource;
import com.example.starter.pass.persist.IdempotentRequestRepository;
import com.example.starter.pass.persist.PredictionRepository;
import com.example.starter.pass.persist.SatelliteRepository;
import com.example.starter.pass.persist.SlotAllocationRepository;
import com.example.starter.pass.persist.StationRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

/**
 * 卫星过境预测、接收时隙分配与遥测确认的业务入口。
 *
 * <p>所有写操作在单事务内完成“加锁 → 校核 → 落库”，失败整体回滚，
 * 不允许留下部分占用或完成标记。</p>
 */
@Service
public class PassService {

    private final StationRepository stationRepository;
    private final SatelliteRepository satelliteRepository;
    private final PredictionRepository predictionRepository;
    private final SlotAllocationRepository slotRepository;
    private final IdempotentRequestRepository idempotentRepository;
    private final TimeSource timeSource;

    public PassService(StationRepository stationRepository,
                       SatelliteRepository satelliteRepository,
                       PredictionRepository predictionRepository,
                       SlotAllocationRepository slotRepository,
                       IdempotentRequestRepository idempotentRepository,
                       TimeSource timeSource) {
        this.stationRepository = stationRepository;
        this.satelliteRepository = satelliteRepository;
        this.predictionRepository = predictionRepository;
        this.slotRepository = slotRepository;
        this.idempotentRepository = idempotentRepository;
        this.timeSource = timeSource;
    }

    /**
     * 提交预测；卫星已有有效版本时即“修订”：新增下一修订版本，旧版本失效，
     * 并把未开始（CONFIRMED）且不满足新窗口/仰角/容量的时隙转为待重新分配；
     * 已完成接收保留旧预测证据。
     */
    @Transactional
    public PredictionView upsertPrediction(PredictionUpsertRequest request) {
        throw new UnsupportedOperationException();
    }

    /**
     * 申请接收时隙：同 requestId 同参重放返回首次结果，异参 409；
     * 依次校核窗口、仰角、容量、天线冲突，任一不满足整体拒绝、不占用部分时隙；
     * 通过后确认，固化预测版本与容量快照。
     */
    @Transactional
    public SlotView allocate(AllocateRequest request) {
        throw new UnsupportedOperationException();
    }

    /**
     * 接收完成回报：同 requestId 同参重放返回首次结果，异参 409；
     * 实际字节不得为负或超过计划量；与取消竞争时只允许一个终态。
     */
    @Transactional
    public SlotView complete(CompleteRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 取消接收计划：仅 CONFIRMED 可取消，释放天线并记录明确取消原因。 */
    @Transactional
    public SlotView cancel(long slotId, CancelRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 待重新分配时隙按卫星最新预测版本重新校核并确认到新站点/窗口。 */
    @Transactional
    public SlotView reassign(long slotId, ReassignRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 预测版本列表（版本时间线），修订号倒序。 */
    @Transactional(readOnly = true)
    public List<PredictionView> getPredictionVersions(String satelliteCode) {
        throw new UnsupportedOperationException();
    }

    /** 某卫星的接收时隙时间线，按窗口起点排序。 */
    @Transactional(readOnly = true)
    public List<SlotView> getTimeline(String satelliteCode) {
        throw new UnsupportedOperationException();
    }

    /** 按状态查询时隙（例如 PENDING_REASSIGN 待重排列表）。 */
    @Transactional(readOnly = true)
    public List<SlotView> getSlotsByStatus(String status) {
        throw new UnsupportedOperationException();
    }

    /** 按主键查时隙（接收实绩、取消原因等）。 */
    @Transactional(readOnly = true)
    public SlotView getSlot(long id) {
        throw new UnsupportedOperationException();
    }

    /** 按分配 requestId 查时隙。 */
    @Transactional(readOnly = true)
    public SlotView findSlotByRequestId(String requestId) {
        throw new UnsupportedOperationException();
    }
}

package com.example.starter.pass.web;

import com.example.starter.pass.api.AllocateRequest;
import com.example.starter.pass.api.CancelRequest;
import com.example.starter.pass.api.CompleteRequest;
import com.example.starter.pass.api.PredictionUpsertRequest;
import com.example.starter.pass.api.PredictionView;
import com.example.starter.pass.api.ReassignRequest;
import com.example.starter.pass.api.SlotView;
import com.example.starter.pass.service.PassService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * 卫星过境接收计划业务入口。
 */
@RestController
@RequestMapping("/api")
public class PassController {

    private final PassService passService;

    public PassController(PassService passService) {
        this.passService = passService;
    }

    /** 提交/修订过境预测，返回固化后的新版本。 */
    @PostMapping("/predictions")
    @ResponseStatus(HttpStatus.CREATED)
    public PredictionView upsertPrediction(@Valid @RequestBody PredictionUpsertRequest request) {
        return passService.upsertPrediction(request);
    }

    /** 预测版本时间线。 */
    @GetMapping("/satellites/{satelliteCode}/predictions")
    public List<PredictionView> predictions(@PathVariable String satelliteCode) {
        return passService.getPredictionVersions(satelliteCode);
    }

    /** 申请接收时隙分配。 */
    @PostMapping("/slots/allocate")
    @ResponseStatus(HttpStatus.CREATED)
    public SlotView allocate(@Valid @RequestBody AllocateRequest request) {
        return passService.allocate(request);
    }

    /** 接收完成回报（遥测确认）。 */
    @PostMapping("/slots/complete")
    public SlotView complete(@Valid @RequestBody CompleteRequest request) {
        return passService.complete(request);
    }

    /** 取消接收计划，释放天线。 */
    @PostMapping("/slots/{slotId}/cancel")
    public SlotView cancel(@PathVariable long slotId, @Valid @RequestBody CancelRequest request) {
        return passService.cancel(slotId, request);
    }

    /** 待重新分配时隙重新分配。 */
    @PostMapping("/slots/{slotId}/reassign")
    public SlotView reassign(@PathVariable long slotId, @Valid @RequestBody ReassignRequest request) {
        return passService.reassign(slotId, request);
    }

    /** 某卫星的时隙时间线（含各状态与接收实绩）。 */
    @GetMapping("/satellites/{satelliteCode}/slots")
    public List<SlotView> timeline(@PathVariable String satelliteCode) {
        return passService.getTimeline(satelliteCode);
    }

    /** 按状态查询时隙，例如 ?status=PENDING_REASSIGN。 */
    @GetMapping("/slots")
    public List<SlotView> slotsByStatus(@RequestParam String status) {
        return passService.getSlotsByStatus(status);
    }

    /** 单个时隙详情。 */
    @GetMapping("/slots/{slotId}")
    public SlotView slot(@PathVariable long slotId) {
        return passService.getSlot(slotId);
    }
}

package com.example.starter.pass.web;

import com.example.starter.pass.api.ErrorBody;
import com.example.starter.pass.domain.BusinessRuleException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 业务异常到 HTTP 响应的统一映射；不向最终用户暴露堆栈。
 */
@RestControllerAdvice
public class PassExceptionHandler {

    /** 可预期规则拒绝：携带可区分原因码与对应状态码。 */
    @ExceptionHandler(BusinessRuleException.class)
    public ResponseEntity<ErrorBody> handleBusiness(BusinessRuleException ex) {
        return ResponseEntity.status(ex.reason().status())
                .body(new ErrorBody(ex.reason().code(), ex.getMessage()));
    }

    /** Bean 校验失败统一按 400 处理。 */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .findFirst()
                .map(e -> e.getField() + " " + e.getDefaultMessage())
                .orElse("invalid request");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody("INVALID_REQUEST", message));
    }

    /** 唯一约束等完整性冲突按 409 处理。 */
    @ExceptionHandler(DataIntegrityViolationException.class)
    public ResponseEntity<ErrorBody> handleIntegrity(DataIntegrityViolationException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new ErrorBody("REQUEST_PARAM_MISMATCH", "conflicting idempotent request"));
    }
}

