    bytes_per_minute    BIGINT       NOT NULL,
    created_at          TIMESTAMP(6) NOT NULL,
    updated_at          TIMESTAMP(6) NOT NULL,
    CONSTRAINT uk_station_code UNIQUE (code),
    CONSTRAINT uk_station_antenna UNIQUE (antenna_code)
);
