    created_at                  TIMESTAMP(6) NOT NULL,
    updated_at                  TIMESTAMP(6) NOT NULL,
    CONSTRAINT uk_slot_request UNIQUE (request_id)
);
COMMENT ON COLUMN slot_allocation.request_id IS '分配幂等requestId，唯一；同参重放返回首次结果，异参冲突';
