            int nextRevision = predictionRepository.findLatest(satellite.getCode())
                    .map(p -> p.getRevisionNo() + 1)
                    .orElse(1);
            predictionRepository.findActive(satellite.getCode())
                    .ifPresent(old -> predictionRepository.markSuperseded(old.getId()));

