                        slot.getWindowStart(), slot.getWindowEnd(),
                        request.visibleStart(), request.visibleEnd(),
                        request.minElevationDeg(), slot.getStationMinElevationDeg(),
                        request.plannedBytes(), slot.getStationBytesPerMinute());
