    private SlotView replayAllocate(AllocateRequest request, String hash) {
        IdempotentRequestPo record = idempotentRepository.findByRequestId(request.requestId())
                .orElseThrow(() -> new BusinessRuleException(RejectReason.NOT_FOUND,
