/**
 * 接收完成回报：requestId 复用分配申请的 requestId；
 * 同参重放返回首次结果，异参 409；实际字节不得为负或超过计划量；
 * 与取消竞争时由行锁与条件 UPDATE 保证只有一个终态。
 */
public SlotView complete(CompleteRequest request) {
    return transactionTemplate.execute(status -> {
        // 幂等键行锁串行化同一 requestId 的并发完成回报。
        IdempotentRequestPo record = idempotentRepository.lockByRequestId(request.requestId())
                .orElseThrow(() -> new BusinessRuleException(RejectReason.NOT_FOUND,
                        "no allocation for requestId: " + request.requestId()));
        if (!OP_ALLOCATE.equals(record.getOperation())) {
            throw new BusinessRuleException(RejectReason.REQUEST_PARAM_MISMATCH,
                    "requestId is not an allocation: " + request.requestId());
        }
        SlotAllocationPo slot = slotRepository.lockById(record.getAllocationId())
                .orElseThrow(() -> new BusinessRuleException(RejectReason.NOT_FOUND,
                        "slot not found: " + record.getAllocationId()));

        AllocationStatus current = AllocationStatus.valueOf(slot.getStatus());
        return switch (current) {
            case RECEIVED -> {
                if (slot.getActualBytes() != null
                        && slot.getActualBytes() == request.actualBytes()) {
                    yield SlotView.from(slot);
                }
                throw new BusinessRuleException(RejectReason.REQUEST_PARAM_MISMATCH,
                        "completion already recorded with different actualBytes for "
                                + request.requestId());
            }
            case CONFIRMED -> {
                SlotRules.checkActualBytes(request.actualBytes(), slot.getPlannedBytes())
                        .ifPresent(r -> {
                            throw new BusinessRuleException(r,
                                    "actual bytes rejected: " + r.code());
                        });
                int updated = slotRepository.markReceived(
                        slot.getId(), request.actualBytes(), timeSource.now());
                if (updated == 0) {
                    throw new BusinessRuleException(RejectReason.SLOT_ALREADY_TERMINATED,
                            "slot reached another terminal state concurrently: " + slot.getId());
                }
                yield SlotView.from(slotRepository.findById(slot.getId()).orElseThrow());
            }
            case CANCELLED -> throw new BusinessRuleException(RejectReason.SLOT_ALREADY_TERMINATED,
                    "slot was cancelled and cannot receive: " + slot.getId());
            case PENDING_REASSIGN -> throw new BusinessRuleException(RejectReason.SLOT_NOT_CONFIRMED,
                    "slot is pending reassign and cannot receive: " + slot.getId());
        };
    });
}

